/**
 * issue #105: the smallest immutable-generation staging/promotion contract
 * needed for a graceful editor-to-runner redeploy handoff.
 *
 * This module is deliberately NOT a general deployment database or
 * generation registry: it holds, in one process's memory, the currently
 * ACTIVE generation (the runner new Workflow starts/ingress should target)
 * and any number of DRAINING generations (previously active, now only
 * expected to keep polling their own Activity task queue for already
 * in-flight Workflows until explicitly retired - issue #68's finding that
 * old and new Activity-queue generations can safely coexist).
 *
 * A "generation" here is exactly the minimal, already-existing set of
 * fields the rest of this runtime uses to pin a Workflow to its execution
 * environment (see lib/worker.js's `temporalConfig`/`flowVersion` handling
 * and root AGENTS.md's "flowVersion is mandatory" rule) - nothing new is
 * invented:
 *   { id, flowVersion, activityTaskQueue, target, userDir }
 * `target` is the runner's Admin API base URL (as already used by
 * lib/remoteDeployStorage.js); `userDir` is documentation-only here (the
 * persistent Node-RED userDir this generation's runner process was/must be
 * started with) - this module never touches the filesystem.
 *
 * Promotion is:
 *   - readiness-gated: the caller-supplied `readinessCheck` MUST resolve
 *     before the active pointer moves; a rejection leaves the previous
 *     generation active and visible (issue #105 P2/P3 requirement).
 *   - serialized: concurrent promote() calls for the same manager run
 *     one-at-a-time via an internal promise-chain mutex, so two racing
 *     Deploys can never invert which generation ends up active.
 *
 * Retirement is explicit and manual only (issue #105 P5): `retire()`
 * requires the caller to supply an `isSafeToRetire(generation)` predicate
 * backed by real Temporal Workflow-handle evidence (e.g.
 * `WorkflowHandle.result()`/`describe()` on every known Workflow ID pinned
 * to that generation's queue) - this module never inspects Temporal
 * Visibility counts itself and never auto-drains/GCs a generation.
 */

"use strict";

const REQUIRED_FIELDS = ["id", "flowVersion", "activityTaskQueue", "target"];

function assertGeneration(generation) {
    if (!generation || typeof generation !== "object") {
        throw new Error("generationManager requires a generation object");
    }
    REQUIRED_FIELDS.forEach(function(field) {
        if (!generation[field]) {
            throw new Error(`generationManager: generation.${field} is required`);
        }
    });
}

/**
 * @returns {{
 *   getActive: function(): (object|null),
 *   listDraining: function(): Array<object>,
 *   promote: function(object, function(): Promise<void>): Promise<object>,
 *   retire: function(string, function(object): Promise<boolean>): Promise<void>
 * }}
 */
function createGenerationManager() {
    let active = null;
    const draining = [];
    // Serializes promote() calls: each call chains onto this promise so a
    // second concurrent Deploy's readiness check/active-pointer flip can
    // only ever start after the first one has fully settled (issue #105
    // P1: "serialize Deploy promotions for one editor").
    let mutex = Promise.resolve();

    function getActive() {
        return active;
    }

    function listDraining() {
        return draining.slice();
    }

    /**
     * @param {object} generation - the staged, immutable generation to
     *   attempt to promote to active.
     * @param {function(): Promise<void>} readinessCheck - must resolve iff
     *   the generation is verified ready (live runtime, matching
     *   flowVersion/queue, Temporal polling, required listeners - issue
     *   #105 P2). A rejection leaves `active` completely untouched.
     * @returns {Promise<object>} the (possibly unchanged) active generation.
     */
    function promote(generation, readinessCheck) {
        if (typeof readinessCheck !== "function") {
            // Programmer-error contract: throw synchronously, mirrors
            // remoteDeployStorage.js's constructor-time argument checks.
            throw new Error("generationManager.promote requires a readinessCheck() function");
        }
        try {
            assertGeneration(generation);
            if (active && active.id === generation.id) {
                throw new Error(`generationManager: generation "${generation.id}" is already active`);
            }
            if (draining.some((g) => g.id === generation.id)) {
                throw new Error(`generationManager: generation "${generation.id}" is already draining, cannot re-promote`);
            }
        } catch (validationErr) {
            return Promise.reject(validationErr);
        }

        const attempt = mutex.then(function() {
            return Promise.resolve()
                .then(readinessCheck)
                .then(function() {
                    if (active) {
                        draining.push(active);
                    }
                    active = generation;
                    return active;
                });
            // On rejection: deliberately no catch here - the rejection
            // propagates to this promote() call's own caller, and `active`
            // was never reassigned, so it remains the previous (or null)
            // generation exactly as before this call (issue #105: "on
            // failed stage/start/readiness ... keep A authoritative").
        });

        // Keep the mutex chain alive for the NEXT promote() call regardless
        // of whether this attempt succeeded or failed, so one failed
        // promotion never wedges the manager for subsequent attempts.
        mutex = attempt.then(
            function() { /* settled ok */ },
            function() { /* settled with error; swallow only for chaining */ }
        );

        return attempt;
    }

    /**
     * @param {string} generationId - a currently DRAINING generation.
     * @param {function(object): Promise<boolean>} isSafeToRetire - must
     *   resolve `true` only once every known Workflow handle pinned to
     *   this generation's Activity task queue has reached a terminal
     *   status (real Workflow evidence - issue #105 P5). Any other result
     *   (including a thrown error) leaves the generation in the draining
     *   list, unretired.
     * @returns {Promise<void>}
     */
    function retire(generationId, isSafeToRetire) {
        if (typeof isSafeToRetire !== "function") {
            throw new Error("generationManager.retire requires an isSafeToRetire() function");
        }
        const index = draining.findIndex((g) => g.id === generationId);
        if (index === -1) {
            if (active && active.id === generationId) {
                return Promise.reject(new Error(`generationManager: generation "${generationId}" is still active, cannot retire the active generation`));
            }
            return Promise.reject(new Error(`generationManager: unknown draining generation "${generationId}"`));
        }
        const generation = draining[index];
        return Promise.resolve()
            .then(function() { return isSafeToRetire(generation); })
            .then(function(safe) {
                if (safe !== true) {
                    throw new Error(`generationManager: retire("${generationId}") refused - isSafeToRetire() did not return true`);
                }
                draining.splice(index, 1);
            });
    }

    return { getActive, listDraining, promote, retire };
}

module.exports = { createGenerationManager };
